package com.academy.lms.course;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="lessons") public class Lesson{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="section_id")private CourseSection section;@Column(nullable=false)private String title;@Column(nullable=false,columnDefinition="text")private String content;@Column(name="video_url")private String videoUrl;@Column(nullable=false)private int position;@Column(name="duration_minutes",nullable=false)private int durationMinutes;@Column(nullable=false)private boolean preview;@Column(name="created_at")private Instant createdAt;protected Lesson(){}public Lesson(CourseSection s,String t,String c,String v,int p,int d,boolean preview){id=UUID.randomUUID();section=s;title=t;content=c;videoUrl=v;position=p;durationMinutes=d;this.preview=preview;createdAt=Instant.now();}public UUID getId(){return id;}public String getTitle(){return title;}public String getContent(){return content;}public String getVideoUrl(){return videoUrl;}public int getPosition(){return position;}public int getDurationMinutes(){return durationMinutes;}public boolean isPreview(){return preview;}public CourseSection getSection(){return section;}}

